import React,{useRef,useState} from 'react';import {createRoot} from 'react-dom/client';import {MemoryRouter} from 'react-router-dom';import ReactQuill from 'react-quill-new';import 'react-quill-new/dist/quill.snow.css';import EditorActions from '../../src/Editor/EditorActions.jsx';import JudgementsPage from '../../src/components/JudgementsPage.jsx';import {SearchProvider} from '../../src/components/Context/searchcontext.jsx';import {deltaBlocks} from '../../src/Editor/exportModel.js';import {pdfBlob} from '../../src/Editor/pdfExport.js';
(async()=>{
const results=[],wait=ms=>new Promise(r=>setTimeout(r,ms)),assert=(condition,message='Assertion failed')=>{if(!condition)throw Error(message);};
const fetchOriginal=window.fetch.bind(window);window.fetch=(url,options)=>{if(new URL(url,location.href).origin!==location.origin)throw Error('External request blocked');return fetchOriginal(url,options);};
async function check(bug,name,fn){try{await fn();results.push({bug,name,pass:true});}catch(e){results.push({bug,name,pass:false,error:e.message});}await fetch('/progress',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(results.at(-1))});}
async function until(fn){for(let i=0;i<120;i++){if(fn())return;await wait(50);}throw Error('Timed out waiting for UI state');}
const root=createRoot(document.getElementById('root'));const button=text=>[...document.querySelectorAll('button')].find(b=>text==='Saved'?b.textContent.trim().startsWith('Saved ')&&!b.textContent.includes('judgements'):b.textContent.trim()===text);
window.__docs=[{id:'123',title:'Synthetic judgement A',court:'Supreme Court',date:'2025-01-01',snippet:'<p>Excerpt A</p>',fulltext:'<p>Legal text A</p>'},{id:'456',title:'Synthetic judgement B',court:'High Court',date:'2025-02-01',snippet:'<p>Excerpt B</p>',fulltext:'<p>Legal text B</p>'}];
sessionStorage.setItem('tnt_draft_session','a'.repeat(64));
const mountPage=()=>root.render(<MemoryRouter><SearchProvider><JudgementsPage/></SearchProvider></MemoryRouter>);
await check('M5','real page saves and lists owner bookmark',async()=>{mountPage();await until(()=>button('Save')&&!button('Save').disabled);button('Save').click();await until(()=>button('Saved')&&!button('Saved').disabled);assert(button('Saved'),[...document.querySelectorAll('button')].map(b=>b.textContent).join(' | ')+': '+document.querySelector('[role="alert"]')?.textContent);button('Saved judgements').click();await wait(30);const panel=document.querySelector('[aria-label="Saved judgements"]');assert(panel.textContent.includes('Synthetic judgement A'));});
await check('M5','saved judgement navigation retains document identifier',async()=>{const panel=document.querySelector('[aria-label="Saved judgements"]');panel.querySelector('button').click();await wait(30);assert(document.body.textContent.includes('Legal text A'));});
await check('M5','reload re-reads server list using authenticated request',async()=>{root.render(<div/>);await wait(20);mountPage();await until(()=>button('Saved')&&!button('Saved').disabled);assert(button('Saved'));});
await check('M5','second user cannot see first user bookmarks in real hook',async()=>{sessionStorage.setItem('tnt_draft_session','b'.repeat(64));mountPage();await until(()=>button('Save')&&!button('Save').disabled);assert(button('Save'));button('Saved judgements').click();await wait(30);assert(document.querySelector('[aria-label="Saved judgements"]').textContent.includes('No saved judgements'));});
await check('M5','owner can remove bookmark without false UI success',async()=>{sessionStorage.setItem('tnt_draft_session','a'.repeat(64));mountPage();await until(()=>button('Saved')&&!button('Saved').disabled);button('Saved').click();await until(()=>button('Save')&&!button('Save').disabled);assert(button('Save'));});
await check('M5','failed save displays failure without successful bookmark state',async()=>{await fetch('/fail-bookmarks',{method:'POST'});button('Save').click();await wait(100);assert(document.querySelector('[role="alert"]')?.textContent.includes('Could not save'));assert(button('Save'));await fetch('/reset-bookmarks',{method:'POST'});});
await check('M5','missing session fails closed with visible error',async()=>{sessionStorage.removeItem('tnt_draft_session');mountPage();await wait(80);assert(document.querySelector('[role="alert"]')?.textContent.includes('Sign in'));assert(button('Sign in again'));});
const unicode=String.fromCodePoint(0x939,0x93f,0x902,0x926,0x940,0x20,0x92e,0x930,0x93e,0x920,0x940,0x20,0x928,0x94d,0x92f,0x93e,0x92f);
window.__unicode=unicode;window.__downloads=[];const anchorClick=HTMLAnchorElement.prototype.click;
HTMLAnchorElement.prototype.click=function(){if(this.download){const name=this.download,url=this.href;window.__downloads.push({name,ready:fetch(url).then(r=>r.blob()).then(async blob=>{await fetch('/artifacts/'+name,{method:'POST',body:blob});})});}else anchorClick.call(this);};
const editorRef=React.createRef();function EditorHarness(){const [text,setText]=useState('');return <><ReactQuill ref={editorRef} value={text} onChange={setText}/><EditorActions manualText={text} setManualText={setText} quillRef={editorRef} setShowChat={()=>{}} setIsTranslating={()=>{}} setIsOCRLoading={()=>{}} setIsAudioLoading={()=>{}} setShowDraftPopup={()=>{}} onOpenScanner={()=>{}} API={location.origin}/></>;}
const fixture={ops:[{insert:'Heading'},{insert:'\n',attributes:{header:2,align:'center'}},{insert:'Bold ',attributes:{bold:true}},{insert:'Italic ',attributes:{italic:true}},{insert:unicode,attributes:{underline:true}},{insert:'\n'},{insert:'First list item'},{insert:'\n',attributes:{list:'ordered'}},{insert:'Second list item'},{insert:'\n',attributes:{list:'ordered'}},{insert:'\n'},{insert:'Final marker END-SAMPLE\n'}]};
await check('M8','real editor retains Delta inline and block formats before export',async()=>{root.render(<EditorHarness/>);await wait(100);editorRef.current.getEditor().setContents(fixture,'user');await wait(40);assert(editorRef.current.getEditor().getText().includes(unicode));assert(editorRef.current.getEditor().root.querySelector('strong'));});
async function uiDownload(label,name){document.querySelector('[title="Save Options"]').click();await wait(20);button(label).click();for(let i=0;i<100;i++){if(window.__downloads.some(d=>d.name===name))break;await wait(100);}const downloaded=window.__downloads.find(d=>d.name===name);assert(downloaded,'No download: '+(document.querySelector('[role="alert"]')?.textContent||name));await downloaded.ready;for(let i=0;i<30&&document.querySelector('[role="status"]');i++)await wait(20);}
await check('M8','PDF UI downloads document.pdf without altering document',async()=>{const before=JSON.stringify(editorRef.current.getEditor().getContents());await uiDownload('Save as PDF','document.pdf');assert(JSON.stringify(editorRef.current.getEditor().getContents())===before);});
await check('M8','Word UI downloads document.docx without altering document',async()=>{const before=JSON.stringify(editorRef.current.getEditor().getContents());await uiDownload('Save as Word','document.docx');assert(JSON.stringify(editorRef.current.getEditor().getContents())===before);});
await check('M8','long mixed-language paragraphs paginate through final marker',async()=>{const lines=Array.from({length:100},(_,i)=>'PARA-'+String(i).padStart(3,'0')+' English '+unicode+' legal document sentence. END-'+String(i).padStart(3,'0'));const blocks=deltaBlocks({ops:[{insert:lines.join('\n')+'\n'}]});const blob=await pdfBlob(blocks);await fetch('/artifacts/long.pdf',{method:'POST',body:blob});});
await check('M8','one long paragraph wraps and paginates without losing text',async()=>{const parts=Array.from({length:160},(_,i)=>'TOKEN-'+String(i).padStart(3,'0')+' '+unicode+' ENDWORD-'+String(i).padStart(3,'0'));const blob=await pdfBlob(deltaBlocks({ops:[{insert:parts.join(' ')+String.fromCharCode(10)}]}));await fetch('/artifacts/single-paragraph.pdf',{method:'POST',body:blob});});
await check('M8','empty PDF export is valid and cleans temporary layout',async()=>{const blob=await pdfBlob(deltaBlocks({ops:[{insert:'\n'}]}));assert(blob.size>0);await fetch('/artifacts/empty.pdf',{method:'POST',body:blob});assert(![...document.querySelectorAll('body>div')].some(d=>d.style.left==='-100000px'));});
await check('M8','unsupported embeds show visible error and do not download',async()=>{editorRef.current.getEditor().setContents({ops:[{insert:{image:'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVQIHWP4z8DwHwAFgAI/ScLbtAAAAABJRU5ErkJggg=='}},{insert:'\n'}]},'user');await wait(30);const count=window.__downloads.length;document.querySelector('[title="Save Options"]').click();await wait(20);button('Save as Word').click();await wait(50);assert(document.querySelector('[role="alert"]')?.textContent.includes('unsupported embeds'));assert(window.__downloads.length===count);});
HTMLAnchorElement.prototype.click=anchorClick;
const pre=document.createElement('pre');pre.id='verification-result';pre.textContent=JSON.stringify(results);document.body.appendChild(pre);
})().catch(error=>{const p=document.createElement('pre');p.id='verification-result';p.textContent=JSON.stringify([{bug:'Harness',name:'completion',pass:false,error:error.message}]);document.body.appendChild(p);});
